import{_ as s,o as e,c as t,a5 as i}from"./chunks/framework.a5no_H3L.js";const k=JSON.parse('{"title":"消息丢失排查","description":"消息丢失的排查需要按环节逐一检查。本文是一个实操排查指南。","frontmatter":{},"headers":[],"relativePath":"kafka/05-troubleshooting/chapter-03-message-loss-debug.md","filePath":"kafka/05-troubleshooting/chapter-03-message-loss-debug.md"}'),l={name:"kafka/05-troubleshooting/chapter-03-message-loss-debug.md"};function r(o,a,d,n,h,c){return e(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="消息丢失排查" tabindex="-1" data-src-line="1" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md">消息丢失排查 <a class="header-anchor" href="#消息丢失排查" aria-label="Permalink to &quot;消息丢失排查&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md"><p data-src-line="3" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md">消息丢失的排查需要按环节逐一检查。本文是一个实操排查指南。</p></blockquote><h2 id="_1-现象" tabindex="-1" data-src-line="5" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md">1. 现象 <a class="header-anchor" href="#_1-现象" aria-label="Permalink to &quot;1. 现象&quot;">​</a></h2><ul data-src-line="7" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md"><li data-src-line="7" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md">消费者处理的消息数量少于生产者发送的数量</li><li data-src-line="8" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md">下游系统缺少预期的数据</li></ul><h2 id="_2-排查步骤" tabindex="-1" data-src-line="10" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md">2. 排查步骤 <a class="header-anchor" href="#_2-排查步骤" aria-label="Permalink to &quot;2. 排查步骤&quot;">​</a></h2><h3 id="step-1-确认丢失环节" tabindex="-1" data-src-line="12" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md">Step 1：确认丢失环节 <a class="header-anchor" href="#step-1-确认丢失环节" aria-label="Permalink to &quot;Step 1：确认丢失环节&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 获取各分区 Offset 边界（log end offset），不是全局消息数量</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kafka-run-class.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kafka.tools.GetOffsetShell</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --broker-list</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost:9092</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --topic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-topic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --time</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -1</span></span></code></pre></div><p data-src-line="20" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md">GetOffsetShell 返回的是各分区的 Offset 边界，不是全局连续的消息计数，不能直接与生产者发送计数相减来定责。定位丢失环节需要端到端证据：</p><ul data-src-line="22" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md"><li data-src-line="22" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md">生产端：核对发送记录与发送回调，确认生产者是否收到成功确认（受 acks 语义约束，acks=0 时不等待 Broker 确认）</li><li data-src-line="23" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md">Broker 侧：按分区核对消费者可见的记录，注意保留策略删除与日志压缩会改变可读记录数，不把 Offset 区间长度当作记录数</li><li data-src-line="24" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md">消费端：核对已提交 Offset、实际处理记录与下游持久化结果是否一致</li></ul><h3 id="step-2-检查生产端" tabindex="-1" data-src-line="26" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md">Step 2：检查生产端 <a class="header-anchor" href="#step-2-检查生产端" aria-label="Permalink to &quot;Step 2：检查生产端&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kafka-topics.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --describe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --topic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-topic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bootstrap-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost:9092</span></span></code></pre></div><p data-src-line="32" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md">检查项：</p><table tabindex="0"><thead data-src-line="34" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md"><tr data-src-line="34" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md"><th style="text-align:left;">检查项</th><th style="text-align:left;">关注点</th></tr></thead><tbody data-src-line="36" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md"><tr data-src-line="36" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md"><td style="text-align:left;">Replication Factor</td><td style="text-align:left;">部署配置，为 1 时无法抵御副本永久损坏，但大于 1 也不自动保证不丢</td></tr><tr data-src-line="37" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md"><td style="text-align:left;">ISR 列表长度</td><td style="text-align:left;">运行状态，短暂小于副本数不等于已丢数据，需观察变化趋势</td></tr><tr data-src-line="38" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md"><td style="text-align:left;">min.insync.replicas</td><td style="text-align:left;">写入约束，需结合 acks=all 与写入时实际 ISR 数量判断</td></tr></tbody></table><h3 id="step-3-检查消费端" tabindex="-1" data-src-line="40" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md">Step 3：检查消费端 <a class="header-anchor" href="#step-3-检查消费端" aria-label="Permalink to &quot;Step 3：检查消费端&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kafka-consumer-groups.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --describe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --group</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-group</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bootstrap-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost:9092</span></span></code></pre></div><p data-src-line="46" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md">检查项：</p><table tabindex="0"><thead data-src-line="48" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md"><tr data-src-line="48" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md"><th style="text-align:left;">信号</th><th style="text-align:left;">需要进一步核实</th></tr></thead><tbody data-src-line="50" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md"><tr data-src-line="50" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md"><td style="text-align:left;">CURRENT-OFFSET</td><td style="text-align:left;">为 -1 通常表示该分区无可用已提交位置，新消费组、尚未提交都可能出现，不代表已丢失</td></tr><tr data-src-line="51" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md"><td style="text-align:left;">提交时机</td><td style="text-align:left;">风险在于提交进度领先于业务实际处理完成的位置，而非自动提交本身</td></tr></tbody></table><h3 id="step-4-检查-broker-日志" tabindex="-1" data-src-line="53" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md">Step 4：检查 Broker 日志 <a class="header-anchor" href="#step-4-检查-broker-日志" aria-label="Permalink to &quot;Step 4：检查 Broker 日志&quot;">​</a></h3><p data-src-line="55" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md">先确定缺失消息所在分区与时间窗口，再检索对应 Broker 的日志，核对 Leader 变更、ISR 收缩、写入失败是否发生在同一时间段：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -iE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;unclean|NotEnoughReplicas&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/kafka-logs/server.log</span></span></code></pre></div><p data-src-line="61" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md">NotEnoughReplicas 说明写入被拒绝，不等于已丢数据；UncleanLeader 选举需与具体分区、Leader 变更时间和数据缺口关联。仅凭关键词命中不能下结论，日志无法确认时需进一步核对分区日志与业务消息 ID。</p><h2 id="_3-可靠性配置核查" tabindex="-1" data-src-line="63" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md">3. 可靠性配置核查 <a class="header-anchor" href="#_3-可靠性配置核查" aria-label="Permalink to &quot;3. 可靠性配置核查&quot;">​</a></h2><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 生产者</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">acks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=all</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">enable.idempotence</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 消费者</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">enable.auto.commit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=false</span></span></code></pre></div><p data-src-line="74" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md">配置调整不能补回已经丢失的数据。分三处核查：</p><ul data-src-line="76" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md"><li data-src-line="76" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md">生产者：核对 <code>acks=all</code>、幂等配置及发送失败处理</li><li data-src-line="77" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md">现有 Topic：核对实际副本因子、<code>min.insync.replicas</code> 与当前 ISR，需要时单独执行副本扩容；<code>default.replication.factor</code> 只影响未显式指定副本因子的自动创建 Topic，不会改动已有 Topic</li><li data-src-line="78" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md">Broker：核对 <code>unclean.leader.election.enable</code>，建议设为 false；这是以可用性为代价降低丢数据风险的选择，并非所有场景唯一正确的值</li></ul><p data-src-line="80" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md">已确认存在数据缺口时，依据生产者记录、备份或上游数据源恢复，不能把参数调整当作数据恢复手段。</p><p data-src-line="82" data-src-file="kafka/05-troubleshooting/chapter-03-message-loss-debug.md">详见 <a href="./../03-reliability/chapter-01-message-loss.html">消息丢失</a>。</p>`,27)])])}const g=s(l,[["render",r]]);export{k as __pageData,g as default};
